import { WeatherstackError, WeatherstackSuccess } from './schema.ts';

/** Why a lookup produced no usable data. Mirrors GraphQL `WeatherFailureReason` (SPEC S5.5). */
export type WeatherFailureReason =
  | 'NETWORK'
  | 'TIMEOUT'
  | 'HTTP_ERROR'
  | 'UPSTREAM_ERROR'
  | 'INVALID_RESPONSE'
  | 'LOCATION_MISMATCH';

export type WeatherLookup =
  | {
      ok: true;
      response: WeatherstackSuccess;
      /** Body exactly as received (lat/lon still strings); used to record test fixtures. */
      raw: unknown;
    }
  | {
      ok: false;
      reason: Exclude<WeatherFailureReason, 'LOCATION_MISMATCH'>;
      /** For logs only. Never contains the access key; never sent to clients. */
      detail: string;
    };

export interface WeatherstackClient {
  /** Exactly one `/current` request; never throws. */
  current(query: string): Promise<WeatherLookup>;
}

export interface WeatherstackClientOptions {
  baseUrl: string;
  accessKey: string;
  timeoutMs?: number;
}

export function createWeatherstackClient({
  baseUrl,
  accessKey,
  timeoutMs = 5000,
}: WeatherstackClientOptions): WeatherstackClient {
  const redact = (text: string) => text.replaceAll(accessKey, '[redacted]');

  return {
    async current(query) {
      const url = new URL('/current', baseUrl);
      url.searchParams.set('access_key', accessKey);
      url.searchParams.set('query', query);
      url.searchParams.set('units', 'f');

      let response: Response;
      try {
        response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
      } catch (error) {
        const timedOut = error instanceof DOMException && error.name === 'TimeoutError';
        return {
          ok: false,
          reason: timedOut ? 'TIMEOUT' : 'NETWORK',
          detail: redact(error instanceof Error ? error.message : String(error)),
        };
      }

      if (!response.ok) {
        return { ok: false, reason: 'HTTP_ERROR', detail: `HTTP ${response.status}` };
      }

      let body: unknown;
      try {
        body = await response.json();
      } catch {
        return { ok: false, reason: 'INVALID_RESPONSE', detail: 'body is not JSON' };
      }

      const upstreamError = WeatherstackError.safeParse(body);
      if (upstreamError.success) {
        const { code, type } = upstreamError.data.error ?? {};
        return {
          ok: false,
          reason: 'UPSTREAM_ERROR',
          detail: redact(`success:false code=${code ?? '?'} type=${type ?? '?'}`),
        };
      }

      const parsed = WeatherstackSuccess.safeParse(body);
      if (!parsed.success) {
        const paths = parsed.error.issues.map((issue) => issue.path.join('.')).join(', ');
        return { ok: false, reason: 'INVALID_RESPONSE', detail: `invalid fields: ${paths}` };
      }
      return { ok: true, response: parsed.data, raw: body };
    },
  };
}

import { z } from 'zod';

/** Weatherstack sends coordinates as strings (SPEC S5.5); accept numbers too, reject non-numeric. */
const coordinate = (min: number, max: number) =>
  z
    .union([z.string().trim().min(1), z.number()])
    .transform(Number)
    .pipe(z.number().min(min).max(max));

/**
 * The `current` object. Fields the UI shows (S4.4) are required; the rest are optional so a
 * missing extra field doesn't block creation. Unknown keys are kept: it's stored as returned.
 */
export const WeatherstackCurrent = z.looseObject({
  observation_time: z.string(),
  temperature: z.number(),
  feelslike: z.number(),
  weather_descriptions: z.array(z.string()),
  weather_icons: z.array(z.string()),
  humidity: z.number(),
  wind_speed: z.number(),
  wind_dir: z.string(),
  weather_code: z.number().optional(),
  wind_degree: z.number().optional(),
  pressure: z.number().optional(),
  precip: z.number().optional(),
  cloudcover: z.number().optional(),
  uv_index: z.number().optional(),
  visibility: z.number().optional(),
  is_day: z.enum(['yes', 'no']).optional(),
});
export type WeatherstackCurrent = z.infer<typeof WeatherstackCurrent>;

export const WeatherstackLocation = z.looseObject({
  country: z.string(),
  region: z.string().optional(),
  name: z.string().optional(),
  lat: coordinate(-90, 90),
  lon: coordinate(-180, 180),
});
export type WeatherstackLocation = z.infer<typeof WeatherstackLocation>;

export const WeatherstackSuccess = z.looseObject({
  location: WeatherstackLocation,
  current: WeatherstackCurrent,
});
export type WeatherstackSuccess = z.infer<typeof WeatherstackSuccess>;

/** HTTP 200 can still be an error: `{ success: false, error: { code, type, info } }`. */
export const WeatherstackError = z.object({
  success: z.literal(false),
  error: z.looseObject({ code: z.number().optional(), type: z.string().optional() }).optional(),
});

