5	import { createPropertyRepository } from '../src/repositories/property.repository.ts';
6	import { createPropertyService } from '../src/services/create-property.service.ts';
7	import { createWeatherstackClient } from '../src/weatherstack/client.ts';
8	import { resetTables, testPrisma } from './database.ts';
9	import { server } from './msw.ts';
10	import { TEST_ACCESS_KEY, weatherstack } from './weatherstack.ts';
11	
12	const app = createApp({
13	  services: {
14	    createProperty: createPropertyService({
15	      properties: createPropertyRepository(testPrisma),
16	      weatherstack: createWeatherstackClient({
17	        baseUrl: 'http://weatherstack.test',
18	        accessKey: TEST_ACCESS_KEY,
19	        timeoutMs: 100,
20	      }),
21	      logger: { warn: () => {} },
22	    }),
23	  },
24	});
25	
26	const CREATE = /* GraphQL */ `
27	  mutation Create($input: CreatePropertyInput!) {
28	    createProperty(input: $input) {
29	      __typename
30	      ... on CreatePropertySuccess {
31	        property {
32	          id
33	          street
34	          city
35	          state
36	          zipCode
37	          lat
38	          long
39	          createdAt
40	          weatherData {
41	            observationTime
42	            temperature
43	            feelsLike
44	            weatherCode
45	            weatherDescriptions
46	            weatherIcons
47	            humidity
48	            windSpeed
49	            windDegree
50	            windDir
51	            pressure
52	            precip
53	            cloudcover
54	            uvIndex
55	            visibility
56	            isDay
57	          }
58	        }
59	      }
60	      ... on InvalidInputError {
61	        message
62	        fieldErrors {
63	          field
64	          message
65	        }
66	      }
67	      ... on DuplicatePropertyError {
68	        message
69	        existingPropertyId
70	      }
71	      ... on WeatherUnavailableError {
72	        message
73	        reason
74	      }
75	    }
76	  }
77	`;
78	
79	const INPUT = {
80	  street: '15528 E Golden Eagle Blvd',
81	  city: 'Fountain Hills',
82	  state: 'AZ',
83	  zipCode: '85268',
84	};
85	
86	/** The `createProperty` payload as selected by CREATE; union members leave the others undefined. */
87	interface CreatePropertyPayload {
88	  __typename: string;
89	  property: { id: string; createdAt: string; weatherData: unknown } & Record<string, unknown>;
90	  message: string;
91	  reason: string;
92	}
93	
94	interface GraphQLResponse {
95	  data?: { createProperty: CreatePropertyPayload };
96	  errors?: { message: string }[];
97	}
98	
99	async function execute(
100	  query: string,
101	  variables: Record<string, unknown>,
102	  target: ReturnType<typeof createApp> = app,
103	) {
104	  const response = await target.fetch('http://api.test/graphql', {
105	    method: 'POST',
106	    headers: { 'content-type': 'application/json' },
107	    body: JSON.stringify({ query, variables }),
108	  });
109	  const text = await response.text();
110	  return { text, body: JSON.parse(text) as GraphQLResponse };
111	}
112	
113	const create = (input: Record<string, unknown> = INPUT) => execute(CREATE, { input });
114	
115	describe('createProperty (GraphQL → Postgres)', () => {
116	  beforeEach(resetTables);
117	  afterAll(() => testPrisma.$disconnect());
118	
119	  it('S5.1 creates the property with weather, lat and long from one Weatherstack call', async () => {
120	    const requests: URL[] = [];
121	    server.use(weatherstack.ok(requests));
122	
123	    const { body } = await create();
124	
125	    expect(requests).toHaveLength(1);
126	    const result = body.data!.createProperty;
127	    expect(result.__typename).toBe('CreatePropertySuccess');
128	    expect(result.property).toMatchObject({ ...INPUT, lat: 33.609, long: -111.729 });
129	    expect(new Date(result.property.createdAt).toISOString()).toBe(result.property.createdAt);
130	    expect(await testPrisma.property.count()).toBe(1);
131	  });
132	
133	  it('S7.2 exposes every Weather field mapped from the stored Weatherstack object', async () => {
134	    server.use(weatherstack.ok());
135	
136	    const { body } = await create();
137	
138	    expect(body.data!.createProperty.property.weatherData).toEqual({
139	      observationTime: '10:35 AM',
140	      temperature: 79,
